CREATE TYPE order_kind AS ENUM ('dine_in','takeaway','delivery');
CREATE TYPE order_state AS ENUM ('pending','accepted','preparing','ready','served','out_for_delivery','completed','cancelled');
CREATE TABLE menu_items (restaurant_id uuid NOT NULL REFERENCES restaurants(id), id text NOT NULL, name text NOT NULL, category text NOT NULL, description text NOT NULL, image text, veg boolean NOT NULL, available boolean NOT NULL DEFAULT true, price_paise integer NOT NULL CHECK(price_paise>=0), half_paise integer CHECK(half_paise>=0), addon_paise integer CHECK(addon_paise>=0), prep_minutes integer NOT NULL CHECK(prep_minutes>0), PRIMARY KEY(restaurant_id,id));
CREATE TABLE orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL REFERENCES restaurants(id), tracking_hash text NOT NULL UNIQUE, request_hash text NOT NULL, kind order_kind NOT NULL, status order_state NOT NULL DEFAULT 'pending', subtotal_paise integer NOT NULL CHECK(subtotal_paise>=0), total_paise integer NOT NULL CHECK(total_paise>=0), instructions text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(restaurant_id,id));
CREATE INDEX orders_restaurant_status_idx ON orders(restaurant_id,status,created_at DESC);
CREATE TABLE order_items (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL, order_id uuid NOT NULL, menu_id text NOT NULL, name text NOT NULL, variant text NOT NULL, addon boolean NOT NULL, unit_paise integer NOT NULL CHECK(unit_paise>=0), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 20), FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id), FOREIGN KEY(restaurant_id,menu_id) REFERENCES menu_items(restaurant_id,id));
CREATE TABLE order_status_history (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), restaurant_id uuid NOT NULL, order_id uuid NOT NULL, status order_state NOT NULL, actor_user_id uuid REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY(restaurant_id,order_id) REFERENCES orders(restaurant_id,id));
